// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        // No precondition needed; the reference always satisfies the rule
        // Drive the contract through its public surface
        vm.prank(c.DEPOSITOR_ACCOUNT());
        c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);
        // Assert the general rule: version() must return "1.0.0"
        assertTrue(keccak256(abi.encodePacked(c.version())) == keccak256(abi.encodePacked("1.0.0")));
    }
}

